<script setup lang="ts">
import { Socket, type Channel } from 'phoenix'
import { BarChart3, Eye, Gamepad2, Search, Shield, Swords, UserRound, UsersRound } from 'lucide-vue-next'
import type { PlayerRatings } from '~/stores/auth'
definePageMeta({ layout: 'default' })
type Status='online'|'offline'|'away'|'dnd';type Category='bullet'|'blitz'|'rapid';type ModeFilter='all'|Category;type ColorFilter='all'|'white'|'black';type Game={id:string;opponent:{nickname:string};color:'white'|'black';result:'win'|'loss'|'draw';end_reason:string|null;rating_change:number|null;rating_category:Category|null;time_control:{id:string;label:string};finished_at:string};type GroupStat={total:number;wins:number;win_rate:number};type DetailedStats={total_games:number;win_rate:number;current_streak:number;best_win_streak:number;by_category:Partial<Record<Category,GroupStat>>;by_color:Partial<Record<'white'|'black',GroupStat>>;by_end_reason:Record<string,number>};type RatingPoint={category:Category;rating_before:number;rating_after:number;change:number;recorded_at:string};type Friend={id:string;nickname:string;avatar_url:string|null;status:Status};type Club={id:string;name:string;description:string|null;avatar_url:string|null;role:string;member_count:number};type Profile={id:string;nickname:string;country:string|null;country_code:string|null;avatar_url:string|null;status:Status;inserted_at:string;ratings:PlayerRatings;stats:{total_games:number;win_rate:number;current_streak:number};detailed_stats:DetailedStats;recent_games:Game[];games:Game[];games_pagination:{page:number;total:number;total_pages:number};rating_history:RatingPoint[];friends:Friend[];friends_count:number;clubs:Club[];profile_views:number};type Tab='overview'|'games'|'stats'|'friends'|'clubs'
const route=useRoute(),auth=useAuthStore(),config=useRuntimeConfig();const profile=ref<Profile|null>(null),loading=ref(true),notFound=ref(false),selectedCategory=ref<Category>('blitz');const searchQuery=ref(String(route.query.q||'')),modeFilter=ref<ModeFilter>(['bullet','blitz','rapid'].includes(String(route.query.category))?String(route.query.category) as Category:'all'),colorFilter=ref<ColorFilter>(['white','black'].includes(String(route.query.color))?String(route.query.color) as ColorFilter:'all');const activeTab=computed<Tab>(()=>['games','stats','friends','clubs'].includes(String(route.query.tab))?String(route.query.tab) as Tab:'overview');const page=computed(()=>Math.max(1,Number(route.query.page)||1));const isOwnProfile=computed(()=>auth.user?.id===profile.value?.id);const displayedStatus=computed(()=>isOwnProfile.value?auth.presence:profile.value?.status||'offline');const ratings=computed(()=>profile.value?[{category:'bullet' as const,label:'Bullet',value:profile.value.ratings.bullet},{category:'blitz' as const,label:'Blitz',value:profile.value.ratings.blitz},{category:'rapid' as const,label:'Rapid',value:profile.value.ratings.rapid}]:[]);const chartPoints=computed(()=>profile.value?.rating_history.filter(p=>p.category===selectedCategory.value)||[]);const chartGeometry=computed(()=>{const values=chartPoints.value.length?[chartPoints.value[0]!.rating_before,...chartPoints.value.map(p=>p.rating_after)]:[];if(!values.length)return{points:'',min:0,max:0,last:0};const min=Math.min(...values),max=Math.max(...values),span=Math.max(max-min,20);return{points:values.map((v,i)=>`${20+(i/Math.max(values.length-1,1))*660},${180-((v-min)/span)*140}`).join(' '),min,max,last:values.at(-1)!}});const tabs=[{id:'overview',label:'Visão geral',icon:UserRound},{id:'games',label:'Partidas',icon:Gamepad2},{id:'stats',label:'Estatísticas',icon:BarChart3},{id:'friends',label:'Amigos',icon:UsersRound},{id:'clubs',label:'Clubes',icon:Shield}] as const
let presenceTimer:ReturnType<typeof setInterval>|null=null,presenceSocket:Socket|null=null,presenceChannel:Channel|null=null,initialView=true,filterDebounceTimer:ReturnType<typeof setTimeout>|null=null
watch([()=>route.params.username,page,()=>route.query.category,()=>route.query.color,()=>route.query.q],()=>{searchQuery.value=String(route.query.q||'');modeFilter.value=['bullet','blitz','rapid'].includes(String(route.query.category))?String(route.query.category) as Category:'all';colorFilter.value=['white','black'].includes(String(route.query.color))?String(route.query.color) as ColorFilter:'all';loadProfile()},{immediate:true});onMounted(()=>{presenceTimer=setInterval(()=>void refreshPresence(),15_000)});onBeforeUnmount(()=>{if(presenceTimer)clearInterval(presenceTimer);presenceChannel?.leave();presenceSocket?.disconnect()});watch(()=>auth.presence,s=>presenceChannel?.push('set_presence',{status:s}))
async function fetchProfile(countView=false){const username=encodeURIComponent(String(route.params.username));const query:Record<string,string|number>={page:page.value,count_view:String(countView)};if(modeFilter.value!=='all')query.category=modeFilter.value;if(colorFilter.value!=='all')query.color=colorFilter.value;if(searchQuery.value.trim())query.q=searchQuery.value.trim();return $fetch<{profile:Profile}>(`/api/users/${username}`,{baseURL:config.public.api.baseURL,headers:auth.token?{Authorization:`Bearer ${auth.token}`}:{},query})}
async function loadProfile(){loading.value=true;notFound.value=false;auth.restoreSession();if(auth.token)await auth.fetchCurrentUser();try{profile.value=(await fetchProfile(initialView)).profile;initialView=false;connectPresence()}catch{profile.value=null;notFound.value=true}finally{loading.value=false}}
function applyFilters(){if(filterDebounceTimer)clearTimeout(filterDebounceTimer);filterDebounceTimer=setTimeout(()=>{const query:Record<string,string>={tab:'games'};if(modeFilter.value!=='all')query.category=modeFilter.value;if(colorFilter.value!=='all')query.color=colorFilter.value;if(searchQuery.value.trim())query.q=searchQuery.value.trim();navigateTo({path:route.path,query})},250)}
async function refreshPresence(){if(!profile.value||document.hidden)return;try{profile.value.status=(await fetchProfile()).profile.status}catch{}}
function connectPresence(){if(presenceSocket||!auth.token||!auth.user||auth.isGuest)return;const url=`${config.public.api.baseURL.replace(/^http/,'ws').replace(/\/$/,'')}/socket`;presenceSocket=new Socket(url,{params:{token:auth.token}});presenceSocket.connect();presenceChannel=presenceSocket.channel('games:lobby',()=>({status:auth.presence}));presenceChannel.on('lobby_updated',()=>void refreshPresence());presenceChannel.join().receive('ok',()=>void refreshPresence())}
function selectTab(tab:Tab){navigateTo({path:route.path,query:tab==='overview'?{}:{tab}})}function goPage(n:number){const query:Record<string,string|number>={tab:'games'};if(n>1)query.page=n;if(modeFilter.value!=='all')query.category=modeFilter.value;if(colorFilter.value!=='all')query.color=colorFilter.value;if(searchQuery.value.trim())query.q=searchQuery.value.trim();navigateTo({path:route.path,query})}function memberSince(v:string){return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(v))}function date(v:string){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v))}function streak(v:number){return!v?'Nenhuma':`${Math.abs(v)} ${v>0?'vitória(s)':'derrota(s)'}`}function resultLabel(v:Game['result']){return v==='win'?'Vitória':v==='loss'?'Derrota':'Empate'}const reasonLabels:Record<string,string>={checkmate:'Xeque-mate',timeout:'Tempo',abandonment:'Abandono',draw:'Empate',other:'Outros'}
</script>
<template><main class="profile-page"><div class="content"><p v-if="loading&&!profile" class="state">Carregando perfil…</p><section v-else-if="notFound" class="state"><strong>Jogador não encontrado</strong><span>Confira o nome informado.</span></section><template v-else-if="profile">
<section class="hero"><ProfilePresenceAvatar :name="profile.nickname" :avatar-url="profile.avatar_url" :status="displayedStatus" :size="92"/><div class="identity"><small>PERFIL DO JOGADOR</small><h1>{{profile.nickname}}</h1><ProfilePresenceStatus :status="displayedStatus"/><p><ProfileCountryFlag v-if="profile.country_code" :code="profile.country_code" show-name/><span v-else>País não informado</span></p><div class="meta"><span>Membro desde {{memberSince(profile.inserted_at)}}</span><span><UsersRound :size="14"/>{{profile.friends_count}} amigos</span><span><Eye :size="14"/>{{profile.profile_views}} visualizações</span></div></div><NuxtLink v-if="isOwnProfile" class="edit" to="/settings/profile">Editar perfil</NuxtLink><NuxtLink v-else-if="auth.user&&!auth.isGuest" class="challenge" :to="{path:'/play',query:{opponent:profile.nickname}}"><Swords :size="18"/>Desafiar</NuxtLink></section>
<nav class="tabs" aria-label="Seções do perfil"><button v-for="tab in tabs" :key="tab.id" :class="{active:activeTab===tab.id}" :aria-current="activeTab===tab.id?'page':undefined" @click="selectTab(tab.id)"><component :is="tab.icon" :size="17"/>{{tab.label}}</button></nav>
<section v-if="activeTab==='overview'" class="tab-content"><div class="ratings"><article v-for="item in ratings" :key="item.category"><div><GameCategoryIcon :category="item.category"/><span>{{item.label}}</span></div><strong>{{item.value}}</strong></article></div><div class="stats summary"><article><strong>{{profile.stats.total_games}}</strong><span>Partidas</span></article><article><strong>{{profile.stats.win_rate}}%</strong><span>Vitórias</span></article><article><strong>{{streak(profile.stats.current_streak)}}</strong><span>Sequência atual</span></article></div><ProfileGameList :games="profile.recent_games" title="Partidas recentes" @all="selectTab('games')"/></section>
<section v-else-if="activeTab==='games'" class="panel games tab-content"><header><h2>Histórico de partidas</h2><span>{{profile.games_pagination.total}} partidas</span></header><div class="game-filters"><div class="search-input"><Search :size="16"/><input v-model="searchQuery" type="text" placeholder="Buscar por oponente…" @input="applyFilters"/></div><div class="filter-selects"><select v-model="modeFilter" @change="applyFilters"><option value="all">Todos os modos</option><option value="bullet">Bullet (1+0)</option><option value="blitz">Blitz (3+0, 5+0)</option><option value="rapid">Rapid (10+0)</option></select><select v-model="colorFilter" @change="applyFilters"><option value="all">Todas as cores</option><option value="white">Brancas ♔</option><option value="black">Pretas ♚</option></select></div></div><p v-if="!profile.games.length" class="empty">Nenhuma partida encontrada com os filtros selecionados.</p><NuxtLink v-for="game in profile.games" :key="game.id" :to="`/game/${game.id}/review`" class="game-row"><b :class="game.result">{{resultLabel(game.result)}}</b><div><strong>vs {{game.opponent.nickname}}</strong><span>{{game.time_control.label}} · {{game.color==='white'?'Brancas':'Pretas'}}</span></div><em v-if="game.rating_change!==null" :class="{positive:game.rating_change>=0}">{{game.rating_change>=0?'+':''}}{{game.rating_change}}</em><time>{{date(game.finished_at)}}</time></NuxtLink><nav v-if="profile.games_pagination.total_pages>1" class="pagination"><button :disabled="page<=1" @click="goPage(page-1)">Anterior</button><span>{{page}} de {{profile.games_pagination.total_pages}}</span><button :disabled="page>=profile.games_pagination.total_pages" @click="goPage(page+1)">Próxima</button></nav></section>
<section v-else-if="activeTab==='stats'" class="tab-content"><section class="panel chart"><header><div><h2>Evolução do rating</h2><span>{{chartGeometry.last||ratings.find(r=>r.category===selectedCategory)?.value}} atual</span></div><div class="category-switch"><button v-for="item in ratings" :key="item.category" :class="{active:selectedCategory===item.category}" @click="selectedCategory=item.category">{{item.label}}</button></div></header><div v-if="chartPoints.length" class="chart-wrap"><svg viewBox="0 0 700 210" role="img"><line x1="20" y1="180" x2="680" y2="180"/><line x1="20" y1="40" x2="680" y2="40"/><polyline :points="chartGeometry.points"/></svg><div><span>{{chartGeometry.min}}</span><span>{{chartPoints.length}} alterações</span><span>{{chartGeometry.max}}</span></div></div><p v-else class="empty">Ainda não há variações nessa modalidade.</p></section><div class="detail-grid"><ProfileStatCard title="Desempenho" :rows="[['Taxa geral',`${profile.detailed_stats.win_rate}%`],['Maior sequência',profile.detailed_stats.best_win_streak],['Sequência atual',streak(profile.detailed_stats.current_streak)]]"/><ProfileStatCard title="Por cor" :rows="[['Brancas',`${profile.detailed_stats.by_color.white?.win_rate||0}% (${profile.detailed_stats.by_color.white?.total||0})`],['Pretas',`${profile.detailed_stats.by_color.black?.win_rate||0}% (${profile.detailed_stats.by_color.black?.total||0})`]]"/><ProfileStatCard title="Por modalidade" :rows="ratings.map(r=>[r.label,`${profile?.detailed_stats.by_category[r.category]?.win_rate||0}% (${profile?.detailed_stats.by_category[r.category]?.total||0})`])"/><ProfileStatCard title="Finais de partida" :rows="Object.entries(profile.detailed_stats.by_end_reason).map(([k,v])=>[reasonLabels[k]||k,v])"/></div></section>
<section v-else-if="activeTab==='friends'" class="panel tab-content"><header><h2>Amigos</h2><span>{{profile.friends_count}}</span></header><p v-if="!profile.friends.length" class="empty">Este jogador ainda não possui amigos.</p><div v-else class="people-grid"><NuxtLink v-for="friend in profile.friends" :key="friend.id" :to="`/user/${friend.nickname}`"><ProfilePresenceAvatar :name="friend.nickname" :avatar-url="friend.avatar_url" :status="friend.status" :size="48"/><div><strong>{{friend.nickname}}</strong><ProfilePresenceStatus :status="friend.status"/></div></NuxtLink></div></section>
<section v-else class="panel tab-content"><header><h2>Clubes</h2><span>{{profile.clubs.length}}</span></header><p v-if="!profile.clubs.length" class="empty">Este jogador ainda não participa de clubes.</p><div v-else class="club-grid"><NuxtLink v-for="club in profile.clubs" :key="club.id" :to="`/social/clubs/${club.id}`"><ClubsClubAvatar :name="club.name" :avatar-url="club.avatar_url" :size="56"/><div><strong>{{club.name}}</strong><span>{{club.member_count}} membros · {{club.role==='admin'?'Administrador':'Membro'}}</span></div></NuxtLink></div></section>
</template></div></main></template>
<style scoped>
.profile-page{min-height:calc(100vh - 60px);padding:clamp(1rem,3vw,2.5rem);color:var(--text);background:var(--bg)}.content{display:grid;width:min(1120px,100%);gap:1rem;margin:auto}.hero,.panel,.ratings article,.stats.summary,.tabs{background:var(--surface);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:1.3rem;padding:1.4rem}.identity{display:grid;justify-items:start}.identity>small{color:var(--accent);font-weight:850;letter-spacing:.12em}.hero h1{margin:.15rem 0;font-size:clamp(2rem,5vw,3.1rem)}.hero p{margin:.45rem 0 0;color:var(--text-muted)}.meta{display:flex;flex-wrap:wrap;gap:.45rem 1rem;margin-top:.65rem;color:var(--text-muted);font-size:.78rem}.meta span{display:flex;align-items:center;gap:.3rem}.edit,.challenge{display:inline-flex;align-items:center;justify-content:center;gap:.45rem;padding:.72rem 1rem;color:var(--accent-ink);background:var(--accent);border-radius:9px;text-decoration:none;font-weight:800}.edit:hover,.challenge:hover{background:var(--accent-hover)}.tabs{display:flex;overflow:auto;padding:.35rem}.tabs button,.category-switch button,.games header button,.pagination button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;padding:.68rem .85rem;color:var(--text-muted);background:transparent;border:0;border-radius:9px;font-weight:750;white-space:nowrap;cursor:pointer}.tabs button.active,.category-switch button.active{color:var(--accent-ink);background:var(--accent)}.tab-content{display:grid;gap:1rem}.ratings{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.ratings article{display:flex;align-items:center;justify-content:space-between;padding:1.15rem}.ratings article div{display:flex;align-items:center;gap:.55rem;color:var(--text-muted)}.ratings strong{color:var(--accent);font-size:1.7rem}.stats.summary{display:grid;grid-template-columns:repeat(3,1fr);padding:1rem}.stats.summary article{display:grid;text-align:center}.stats.summary article+article{border-left:1px solid var(--border-subtle)}.panel{padding:1.25rem}.panel>header,.chart>header{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.8rem}.panel h2{margin:0;font-size:1.05rem}.panel header>span,.empty{color:var(--text-muted)}.game-filters{display:flex;flex-wrap:wrap;gap:.75rem;margin-bottom:.85rem}.search-input{display:flex;align-items:center;gap:.55rem;flex:1 1 220px;padding:.55rem .85rem;background:var(--surface-strong);border:1px solid var(--border-subtle);border-radius:9px;color:var(--text-muted)}.search-input input{flex:1;background:transparent;border:0;outline:0;color:var(--text);font-size:.88rem;font-family:var(--font-sans)}.search-input input::placeholder{color:var(--text-muted)}.filter-selects{display:flex;gap:.6rem;flex-wrap:wrap}.filter-selects select{padding:.55rem .85rem;color:var(--text);background:var(--surface-strong);border:1px solid var(--border-subtle);border-radius:9px;font:600 .85rem var(--font-sans);outline:0;cursor:pointer}.filter-selects select:hover{border-color:var(--border)}.game-row{display:grid;grid-template-columns:76px 1fr auto 100px;align-items:center;gap:.8rem;padding:.8rem 0;color:var(--text);border-top:1px solid var(--border-subtle);text-decoration:none}.game-row div{display:grid}.game-row span,.game-row time{color:var(--text-muted);font-size:.8rem}.game-row b{color:var(--text-muted)}.game-row b.win,.game-row em.positive{color:var(--success)}.game-row b.loss,.game-row em{color:var(--danger)}.game-row b,.game-row strong{transition:color 140ms ease}.game-row:hover b,.game-row:hover strong{color:var(--accent)!important}.game-row em{font-style:normal;font-weight:800}.pagination{display:flex;align-items:center;justify-content:center;gap:1rem;margin-top:1rem}.category-switch{display:flex;gap:.25rem;padding:.2rem;background:var(--surface-strong);border-radius:10px}.chart header span{color:var(--text-muted);font-size:.8rem}.chart-wrap{overflow:hidden}.chart-wrap svg{width:100%;min-width:520px}.chart-wrap line{stroke:var(--border-subtle)}.chart-wrap polyline{fill:none;stroke:var(--accent);stroke-width:4;stroke-linecap:round;stroke-linejoin:round}.chart-wrap>div{display:flex;justify-content:space-between;color:var(--text-muted);font-size:.72rem}.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}:deep(.stat-card dl){margin:.8rem 0 0}:deep(.stat-card dl div){display:flex;justify-content:space-between;padding:.65rem 0;border-top:1px solid var(--border-subtle)}:deep(.stat-card dt){color:var(--text-muted)}:deep(.stat-card dd){margin:0;font-weight:800}.people-grid,.club-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem}.people-grid a,.club-grid a{display:flex;align-items:center;gap:.8rem;padding:.85rem;color:var(--text);background:var(--surface-strong);border:1px solid var(--border-subtle);border-radius:11px;text-decoration:none}.people-grid a>div,.club-grid a>div{display:grid;gap:.25rem}.club-grid span{color:var(--text-muted);font-size:.78rem}.state,.empty{padding:2rem;text-align:center}@media(max-width:720px){.hero{grid-template-columns:auto 1fr}.edit,.challenge{grid-column:1/-1;text-align:center}.ratings,.detail-grid,.people-grid,.club-grid{grid-template-columns:1fr}.game-row{grid-template-columns:68px 1fr auto}.game-row time{display:none}.chart>header{align-items:stretch;flex-direction:column}.tabs button{flex:1}.tabs button svg{display:none}.game-filters{flex-direction:column}.filter-selects{width:100%}.filter-selects select{flex:1}}@media(max-width:480px){.hero{grid-template-columns:1fr;justify-items:center;text-align:center}.identity{justify-items:center}.meta{justify-content:center}.stats.summary{grid-template-columns:1fr;gap:.8rem}.stats.summary article+article{padding-top:.8rem;border-top:1px solid var(--border-subtle);border-left:0}}
</style>
